import{_ as d,o as r,c as a,a5 as e}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"AI 任务简报：从问题到人工验收","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/ai-task-brief.zh.md","filePath":"public/downloads/worksheets/ai-task-brief.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/ai-task-brief.zh.md"};function i(b,t,l,o,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="ai-任务简报-从问题到人工验收" tabindex="-1">AI 任务简报：从问题到人工验收 <a class="header-anchor" href="#ai-任务简报-从问题到人工验收" aria-label="Permalink to &quot;AI 任务简报：从问题到人工验收&quot;">​</a></h1><p>复制到私有项目目录，在模型调用前填写。它不是 prompt 收集器，而是一张开始许可：如果任务、数据、来源、验收或责任人仍然不清楚，就先不要让模型生成最终结果。</p><p>不要写入密码、证件、精确住址、医疗隐私、儿童数据、客户记录、未公开漏洞或无权使用的第三方内容。敏感材料先脱敏，或改用组织批准的环境。</p><h2 id="_1-任务与责任" tabindex="-1">1. 任务与责任 <a class="header-anchor" href="#_1-任务与责任" aria-label="Permalink to &quot;1. 任务与责任&quot;">​</a></h2><h3 id="ai-task-brief-yyyy-mm-dd" tabindex="-1">AI Task Brief - YYYY-MM-DD <a class="header-anchor" href="#ai-task-brief-yyyy-mm-dd" aria-label="Permalink to &quot;AI Task Brief - YYYY-MM-DD&quot;">​</a></h3><p>真实场景：<br> 使用者/受众：<br> 要完成的决策或动作：<br> 为什么现在做：<br> 截止时间与不可错过的节点：<br> 最终负责人与人工审阅者：<br> 如果不做或延迟，谁会受影响：</p><p>把“学 AI”“做一个智能助手”改成可观察的动作，例如“用户能在 10 分钟内导入一份文件，并看到一份能解释来源和错误的报告”。</p><h2 id="_2-输入、来源与数据边界" tabindex="-1">2. 输入、来源与数据边界 <a class="header-anchor" href="#_2-输入、来源与数据边界" aria-label="Permalink to &quot;2. 输入、来源与数据边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入/主张</th><th>类型</th><th>来源、版本与位置</th><th>可否提供给模型</th><th>核验人</th><th>失效条件</th></tr></thead><tbody><tr><td></td><td>事实 / 推断 / 个人经验 / 用户数据 / 第三方内容</td><td></td><td>公开 / 脱敏 / 组织批准 / 禁止</td><td></td><td></td></tr></tbody></table><p>允许使用的文件和字段：<br> 明确不提供的材料：<br> 数据敏感等级：公开 / 内部 / 机密 / 受限<br> 收集、传输、留存和删除期限：<br> 是否取得必要同意：<br> 版权、许可证、引用和署名要求：<br> 模型能接触的最小数据范围：</p><p>来源不等于真相。每个关键主张要能回到原文、版本、数据口径或直接观察；模型给出的链接、数字和引语仍需人工核验。</p><h2 id="_3-输出与评估集" tabindex="-1">3. 输出与评估集 <a class="header-anchor" href="#_3-输出与评估集" aria-label="Permalink to &quot;3. 输出与评估集&quot;">​</a></h2><p>最终交付物：<br> 格式、长度和受众：<br> 可观察的完成标准：<br> 必须通过的硬门：<br> 允许的可接受变体：<br> 明确不能出现的内容：</p><p>建立一份小而真实的评估集，不要只用模型最擅长的示例：</p><table tabindex="0"><thead><tr><th>样本</th><th>输入条件</th><th>预期结果</th><th>不可接受结果</th><th>实测结果</th><th>证据位置</th></tr></thead><tbody><tr><td>正常样本</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>边界样本</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>缺失/冲突输入</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>真实历史样本（已脱敏）</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>验收至少回答：事实是否可追溯，关键动作是否完成，错误是否可见，权限是否正确，失败是否可停止。流畅、快速或“像人”不是验收标准。</p><h2 id="_4-ai-的工作范围" tabindex="-1">4. AI 的工作范围 <a class="header-anchor" href="#_4-ai-的工作范围" aria-label="Permalink to &quot;4. AI 的工作范围&quot;">​</a></h2><p>AI 可以做：提问 / 分类 / 候选解释 / 反例 / 转写 / 草稿 / 测试建议<br> AI 不可以做：最终事实判断 / 虚构来源 / 代替责任人批准 / 越过权限<br> / 完成禁止外部帮助的考试或申请 / 自动发布<br> 使用模式：诊断 / 辅助 / 生成候选 / 批量处理 / 其他<br> 模型、版本、区域和调用日期：<br> 外部工具、MCP 服务器或其他协议及版本：<br> 每个工具的读取/写入范围、授权人和撤回方式：<br> 提示词、系统指令或工作流版本位置：</p><p>如果任务会长时间运行或调用外部工具，还要记录：</p><p>运行/任务编号及父任务编号：<br> 异步或同步；预计与最大墙钟时间：<br> 检查点位置与恢复步骤：<br> 最大重试次数、超时和重复安全标识：<br> 浏览器页面、截图和外部指令均视为不可信输入：<br> 网络出口白名单与凭证范围：<br> 外部写入、收据和最终环境状态：<br> 人工接管点与紧急停止方式：<br> 供应商政策/版本、生效日期、地区和高风险复核：</p><p>先让模型复述目标、输入、限制、未知项和验收，再开始生成。提示词版本化；不要把一次聊天窗口当作唯一的项目记录。</p><h2 id="_5-人工门" tabindex="-1">5. 人工门 <a class="header-anchor" href="#_5-人工门" aria-label="Permalink to &quot;5. 人工门&quot;">​</a></h2><table tabindex="0"><thead><tr><th>门</th><th>必须由谁确认</th><th>通过证据</th><th>未通过时</th></tr></thead><tbody><tr><td>来源门</td><td></td><td>原始链接、版本、位置</td><td>标记未核验，不传播</td></tr><tr><td>事实门</td><td></td><td>抽样核对、数据口径</td><td>删除或降级主张</td></tr><tr><td>隐私/权限门</td><td></td><td>数据范围、同意、访问日志</td><td>停止处理并脱敏</td></tr><tr><td>质量门</td><td></td><td>评估集、边界样本、真实反馈</td><td>修复、缩小或拒绝交付</td></tr><tr><td>成本门</td><td></td><td>token、时间、人工返工与预算</td><td>降级模型或停止</td></tr><tr><td>工具授权门</td><td></td><td>工具范围、调用记录、具名授权和撤回方式</td><td>禁止调用或回到人工</td></tr><tr><td>责任门</td><td></td><td>具名批准和披露文字</td><td>不发布、不自动执行</td></tr></tbody></table><p>关键决定不能只由生成模型、自动评分或单个开发者自己批准。高风险领域回到当前一手材料和合格专业人员。</p><h2 id="_6-成本、留存与可逆性" tabindex="-1">6. 成本、留存与可逆性 <a class="header-anchor" href="#_6-成本、留存与可逆性" aria-label="Permalink to &quot;6. 成本、留存与可逆性&quot;">​</a></h2><p>预计调用量、时间和费用上限：<br> 人工审阅与返工预算：<br> 数据是否进入训练、日志或第三方留存：<br> 可接受延迟与降级方案：<br> 可以撤回、重跑或恢复到哪个版本：<br> 发布范围与灰度对象：</p><p>一次便宜的调用如果造成隐私事件、错误决定或大量返工，真实成本并不便宜。记录模型费用之外的人工时间、审阅、失败、重跑和沟通成本。</p><h2 id="_7-失败、暂停与回滚" tabindex="-1">7. 失败、暂停与回滚 <a class="header-anchor" href="#_7-失败、暂停与回滚" aria-label="Permalink to &quot;7. 失败、暂停与回滚&quot;">​</a></h2><table tabindex="0"><thead><tr><th>触发条件</th><th>立即动作</th><th>通知谁</th><th>恢复/回滚位置</th></tr></thead><tbody><tr><td>找不到来源或版本</td><td>停止传播，回到原始材料</td><td></td><td></td></tr><tr><td>评估集硬门失败</td><td>禁止发布或自动执行</td><td></td><td></td></tr><tr><td>输入越过权限边界</td><td>停止上传，撤销访问</td><td></td><td></td></tr><tr><td>成本/延迟超过上限</td><td>降级、限流或停止</td><td></td><td></td></tr><tr><td>真实用户报告伤害</td><td>下线、保留证据、升级处理</td><td></td><td></td></tr></tbody></table><p>如果没有明确的停止人、通知路径和已知可用版本，就还没有准备好接入真实流程。</p><h2 id="_8-交接与公开说明" tabindex="-1">8. 交接与公开说明 <a class="header-anchor" href="#_8-交接与公开说明" aria-label="Permalink to &quot;8. 交接与公开说明&quot;">​</a></h2><p>当前状态：未开始 / 实验 / 内部试用 / 灰度 / 已交付 / 已停止<br> 已完成与证据位置：<br> 未决问题和风险：<br> 下一项最小任务：<br> 交接负责人、时间和权限：<br> 读者/用户需要知道的 AI 参与范围：<br> 来源、隐私、版权和利益关系说明：</p><p>交接者不应需要翻找聊天记录才能知道下一步。公开文本至少说明工具参与了哪一步、哪些事实由人确认、哪些内容仍是候选。</p><h2 id="_9-开始前检查" tabindex="-1">9. 开始前检查 <a class="header-anchor" href="#_9-开始前检查" aria-label="Permalink to &quot;9. 开始前检查&quot;">​</a></h2><ul><li>[ ] 真实受众、动作、截止时间和负责人已写清；</li><li>[ ] 输入字段、敏感等级、同意、版权和留存边界已确认；</li><li>[ ] 关键来源、版本和失效条件可回溯；</li><li>[ ] 正常、边界、冲突和历史脱敏样本已进入评估集；</li><li>[ ] AI 可以做与不可以做的范围已写清；</li><li>[ ] 适用时已记录长时任务检查点、重试/重复安全规则、浏览器输入边界和网络出口；</li><li>[ ] 人工门、费用上限、停止条件和回滚位置已指定；</li><li>[ ] 交接、披露和下一次复查日期已确定。</li></ul><hr><p>来源：<a href="https://byoungd.github.io/up/templates/ai-task-brief" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-10-16。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',37)])])}const _=d(h,[["render",i]]);export{c as __pageData,_ as default};
